			row[USCTariffSchema.Constants.UE_ShortDescription               ] = "";
			row[USCTariffSchema.Constants.UE_SPICode                        ] = "";
			row[USCTariffSchema.Constants.UE_Tariff                         ] = "";
			row[USCTariffSchema.Constants.UE_TextileCategoryNumber          ] = "";
			row[USCTariffSchema.Constants.UE_Unit1                          ] = "";
			row[USCTariffSchema.Constants.UE_Unit2                          ] = "";
			row[USCTariffSchema.Constants.UE_Unit3                          ] = "";
		}

		#endregion

		#region Lookups

		public USCTariffLookups Lookups
		{
			get
			{
				if (fLookups == null || !IsLookupsCachedInBase)
				{
					fLookups = GetNewLookups();
				}

				return fLookups;
			}
		}

		protected virtual USCTariffLookups GetNewLookups()
		{
			return new USCTariffLookups(this);
		}

		USCTariffLookups fLookups;

		#endregion

		#region Validation

		protected override void RunPreSaveValidationCore()
		{
			Validation.ValidateAll();
			base.RunPreSaveValidationCore(); // call RunPreSaveValidationCore() on all children then fire OnNotificationsChanged()
		}

		public USCTariffValidation Validation
		{
			get { return GetNewValidation(); }
		}

		protected virtual USCTariffValidation GetNewValidation()
		{
			return new USCTariffValidation(this);
		}

		#endregion
	}
}
